/**
 * BLS LAUS monthly unemployment, as generated by scripts/bls into
 * data/generated/bls-laus.json. The site never calls BLS: everything here
 * comes from that committed file. Values are exactly what BLS publishes;
 * missing stays null.
 */
import laus from "../../../data/generated/bls-laus.json";
import {
  monthLabel as formatMonthLabel,
  monthShort as formatMonthShort,
} from "../../i18n/format.ts";
import type { Locale } from "../../i18n/locale.ts";

export type LausMeasure = "rate" | "laborForce" | "employment" | "unemployment";

type Block = { series: Record<LausMeasure, string> } & Record<LausMeasure, (number | null)[]>;

type Laus = {
  source: {
    agency: string;
    dataset: string;
    api: string;
    page: string;
    retrievedAt: string;
    seasonalAdjustment: string;
    terms: { disclaimer: string; copyright: string; api: string };
  };
  months: string[];
  latest: string;
  preliminary: string[];
  puertoRico: Block;
  municipios: Record<string, { name: string } & Block>;
};

const data = laus as unknown as Laus;

export const LAUS_SOURCE = data.source;
export const LAUS_MONTHS = data.months;
export const LAUS_LATEST = data.latest;
const LATEST_INDEX = data.months.indexOf(data.latest);

/** "2026-08" → "agosto de 2026" / "August 2026". */
export function monthLabel(key: string, locale: Locale = "es"): string {
  return formatMonthLabel(key, locale);
}

/** "2026-08" → "ago 2026" / "Aug 2026". */
export function monthShort(key: string, locale: Locale = "es"): string {
  return formatMonthShort(key, locale);
}

export function isPreliminary(key: string): boolean {
  return data.preliminary.includes(key);
}

export const LAUS_LATEST_LABEL = monthLabel(LAUS_LATEST);
export const LAUS_LATEST_PRELIMINARY = isPreliminary(LAUS_LATEST);

export function lausBlock(id: string | null): Block | null {
  if (!id) return data.puertoRico;
  return data.municipios[id] ?? null;
}

/** Latest-month unemployment rate for every municipio (null when BLS did not publish one). */
export function latestRates(): Record<string, number | null> {
  return Object.fromEntries(
    Object.entries(data.municipios).map(([id, block]) => [id, block.rate[LATEST_INDEX] ?? null]),
  );
}

export type Comparison = { key: string; label: string; value: number | null; preliminary: boolean };

/** Latest month, the month before and the same month a year earlier, for one measure. */
export function comparisons(
  id: string | null,
  measure: LausMeasure = "rate",
): { latest: Comparison; previous: Comparison | null; yearAgo: Comparison | null } | null {
  const block = lausBlock(id);
  if (!block) return null;
  const at = (index: number): Comparison | null =>
    index < 0
      ? null
      : {
          key: data.months[index],
          label: monthLabel(data.months[index]),
          value: block[measure][index],
          preliminary: isPreliminary(data.months[index]),
        };
  return {
    latest: at(LATEST_INDEX)!,
    previous: at(LATEST_INDEX - 1),
    yearAgo: at(LATEST_INDEX - 12),
  };
}

/** The last `count` months of a measure, oldest first, for a small trend line. */
export function trend(
  id: string | null,
  measure: LausMeasure = "rate",
  count = 24,
): { key: string; value: number | null }[] {
  const block = lausBlock(id);
  if (!block) return [];
  const start = Math.max(0, LATEST_INDEX - count + 1);
  return data.months
    .slice(start, LATEST_INDEX + 1)
    .map((key, i) => ({ key, value: block[measure][start + i] }));
}
